'use strict';
const controlUi=Object.fromEntries(['control-summary','control-search','control-group','control-status','control-results','control-list','control-more'].map(id=>[id,document.getElementById(id)]));
let controls=[],limit=60;
function line(parent,label,value){if(!value)return;const p=document.createElement('p');const strong=document.createElement('strong');strong.textContent=label+' ';p.append(strong,document.createTextNode(Array.isArray(value)?value.join('; '):String(value)));parent.append(p);}
function renderControls(){const term=controlUi['control-search'].value.trim().toLowerCase(),group=controlUi['control-group'].value,status=controlUi['control-status'].value;const matches=controls.filter(c=>(!group||c.group===group)&&(!status||c.status===status)&&(!term||(c.id+' '+c.text).toLowerCase().includes(term)));const fragment=document.createDocumentFragment();for(const c of matches.slice(0,limit)){const section=document.createElement('section');section.className='control-record briefing-card';const heading=document.createElement('h2');heading.textContent=c.id+' · '+c.status.replaceAll('_',' ');section.append(heading);line(section,'Requirement:',c.text);line(section,'Component:',c.groupTitle);line(section,'Implementation:',c.implementation_reference||'No complete implementation reference accepted');line(section,'Evidence:',c.evidence_references.length?c.evidence_references:'No matching verification evidence accepted');line(section,'Outstanding:',c.gap);line(section,'Assessment:',c.assessment_note);fragment.append(section);}controlUi['control-list'].replaceChildren(fragment);controlUi['control-results'].textContent=`Showing ${Math.min(limit,matches.length)} of ${matches.length} matching controls.`;controlUi['control-more'].hidden=limit>=matches.length;}
for(const id of ['control-search','control-group','control-status'])controlUi[id].addEventListener('input',()=>{limit=60;renderControls();});controlUi['control-more'].addEventListener('click',()=>{limit+=60;renderControls();});
(async()=>{try{const response=await fetch('/api/controls',{cache:'no-store'});if(!response.ok)throw new Error('Control assessment is unavailable.');const data=await response.json();for(const g of data.groups){const option=document.createElement('option');option.value=g.id;option.textContent=g.id+' · '+g.title;controlUi['control-group'].append(option);for(const p of g.controls)for(const c of p.children)controls.push({...c,group:g.id,groupTitle:g.title});}const s=data.summary;controlUi['control-summary'].textContent=`${s.total_children.toLocaleString()} subcontrols · ${s.parents} parent controls · ${s.statuses.verified||0} verified · ${s.unverified.toLocaleString()} awaiting full verification. Full release: ${s.complete_release_allowed?'accepted':'blocked'}.`;renderControls();}catch(error){controlUi['control-summary'].textContent=error.message;}})();
